package com.receiptledger.v1.recovery;
public final class RecoveryScalePlanner {private RecoveryScalePlanner(){}public static Plan plan(int width,int height,int maxEdge,long maxPixels){if(width<1||height<1||maxEdge<2||maxPixels<4)throw new IllegalArgumentException();double scale=Math.min(1.0,Math.min(maxEdge/(double)Math.max(width,height),Math.sqrt(maxPixels/((double)width*height))));return new Plan(Math.max(2,(int)Math.round(width*scale)),Math.max(2,(int)Math.round(height*scale)));}public static final class Plan{public final int width,height;Plan(int w,int h){width=w;height=h;}}}
